  let timer: NodeJS.Timeout | undefined;
  const budget = new Promise<never>((_, reject) => {
    timer = setTimeout(() => {
      state.over = true;
      reject(
        new Error(
          `route ${route} exceeded its ${ROUTE_BUDGET_MS / 1000}s capture budget; requests still in flight: ${describePending(page)}`,
